package com.habla.espanol;

/** Short grammar cards explaining the rules behind the phrases the user practices. */
final class GrammarTips {
    private GrammarTips() {}

    /** {title, explanation} — Egyptian-Arabic explanations. */
    static final String[][] TIPS = {
        {"ser ولا estar؟", "«ser» بيتقال للصفات الثابتة: الهوية والأصل والوظيفة. مثل: «Soy egipcio» و«Soy estudiante».\n«estar» بيتقال للحالة المؤقتة أو المكان. مثل: «Estoy cansado» و«Estoy en casa»."},
        {"أدوات التعريف", "«el» للمذكر المفرد، «la» للمؤنث المفرد، و«los/las» للجمع.\nملاحظة مهمة: قول «el agua» مش «la agua»، لأن كلمة «agua» بتبدأ بـ«a» قوي."},
        {"المذكر والمؤنث", "أغلب الكلمات اللي على «-o» مذكر واللي على «-a» مؤنث. والصفات تتبع الاسم: «el apartamento pequeño» و«la casa pequeña».\nاستثناءات تحفظها: «la mano» مؤنث، و«el día» و«el problema» مذكرين."},
        {"الجمع", "الكلمة اللي بتخلص على حرف علة ضيف لها «s»، واللي بتخلص على ساكن ضيف لها «es».\nمثل: «la casa» تبقى «las casas»، و«el hotel» يبقى «los hoteles»."},
        {"تصريف منتظم مع yo", "خد الجذر من المصدر وضيف «o»:\n«hablar» تبقى «hablo»، و«comer» تبقى «como»، و«vivir» تبقى «vivo»."},
        {"ser و estar بالكامل", "«ser»: soy, eres, es, somos, sois, son.\n«estar»: estoy, estás, está, estamos, estáis, están.\nاحفظهما سوا مرة واحدة، لأنهما أساس أي جملة إسبانية."},
        {"خمسة أفعال احفظها زي ما هي", "tengo = عندي، quiero = عايز، puedo = أقدر، hago = بعمل، voy = بأمشي.\nهما مش منتظمين في التصريف، لكن الدروس بيكرروهم لحد ما يثبتوا."},
        {"المستقبل البسيط: ir a", "حب «ir a» قبل أي مصدر تبقى «ناوي أعمل».\n«Voy a estudiar» = سأدرس، و«Vamos a empezar» = نبدا."},
        {"hay — يوجد", "«Hay un problema» يعني في مشكلة. كلمة «hay» بتقول يوجد.\nوعشان تقول إنك في مكان: «Estoy en casa»."},
        {"Me gusta", "«Me gusta el café» يعني القهوة عجباني.\nلو الكلمة جمع: «Me gustan las manzanas» يعني التفاحات عجباني."},
        {"النفي القوي", "بعد «no» ضيف «nada» لقوة المعنى: «No me gusta nada» يعني مبيجيش خالص.\nالنفي المزدوج في الإسبانية صح ومطلوب."},
        {"كلمات السؤال", "«¿qué?» = ماذا، «¿quién?» = من، «¿dónde?» = أين، «¿cuándo?» = متى، «¿cómo?» = كيف، «¿cuánto?» = كم، «¿por qué?» = لماذا.\nكل سؤال إسباني بيبدأ بعلامة «¿»."},
        {"por ولا para؟", "«por» للسبب والوقت: «Gracias por tu ayuda» و«por la mañana».\n«para» للهدف والملكية: «para mí» و«Para llevar, por favor»."},
        {"الطلب المهذب", "مع شخص محترم استخدم «usted»: اسأل بصيغة «¿Puede...?».\nمع الأصحاب استخدم «¿Puedes...?».\nفي المقهى والمطعم: «¿Me pone...?» و«¿Me trae...?»."},
        {"vosotros و ustedes", "في إسبانيا بتكلم الأصحاب بصيغة «vosotros»: مثل «¿Sois estudiantes?».\nفي المكسيك وبيرو تسيبها وتقول «ustedes»."},
        {"الساعة", "«Es la una» يعني الساعة الواحدة.\nباقي الساعات تقال جمع: «Son las tres»، وللنص: «Son las tres y media»."},
    };
}
